-- Improvement 2: notifications.
--
-- Until now the only way to learn that something happened was to go looking.
-- A task assigned to you, or a comment on a task you own, produced no signal
-- at all.
--
-- Notifications are generated by database triggers rather than application
-- code. The rules that create work -- assignment, comments -- are enforced in
-- Postgres, so the signal that work arrived belongs there too. Anything that
-- writes to these tables, including a future script or the API directly,
-- produces notifications without having to remember to.

create table if not exists notifications (
  id          uuid primary key default gen_random_uuid(),
  person_id   uuid not null references people (id) on delete cascade,
  kind        text not null check (kind in ('assigned', 'comment', 'message', 'announcement')),
  -- What it is about. Kept nullable so deleting the subject does not erase
  -- the fact that you were told.
  task_id     uuid references tasks (id) on delete cascade,
  actor_id    uuid references people (id) on delete set null,
  summary     text not null,
  url         text not null,
  read_at     timestamptz,
  created_at  timestamptz not null default now()
);

create index if not exists notifications_person_idx
  on notifications (person_id, read_at, created_at desc);

alter table notifications enable row level security;

-- Strictly your own. A notification can reveal the existence of a task you
-- would not otherwise see, so this is narrower than the task rules.
drop policy if exists "read own notifications" on notifications;
create policy "read own notifications" on notifications
  for select to authenticated
  using (person_id = current_person_id());

-- Marking as read is the only change you make; the row itself is written by
-- triggers running as the database, not by the client.
drop policy if exists "mark own notifications" on notifications;
create policy "mark own notifications" on notifications
  for update to authenticated
  using (person_id = current_person_id())
  with check (person_id = current_person_id());

drop policy if exists "clear own notifications" on notifications;
create policy "clear own notifications" on notifications
  for delete to authenticated
  using (person_id = current_person_id());

-- No insert policy: nothing signed in may invent a notification for anyone.

-- Being tagged onto a task.
create or replace function notify_task_assigned()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  v_actor uuid := current_person_id();
  v_title text;
begin
  select title into v_title from tasks where id = new.task_id;

  -- Tagging yourself is not news.
  if new.person_id is distinct from v_actor then
    insert into notifications (person_id, kind, task_id, actor_id, summary, url)
    values (
      new.person_id,
      'assigned',
      new.task_id,
      v_actor,
      coalesce((select full_name from people where id = v_actor), 'Someone')
        || ' tagged you on "' || coalesce(v_title, 'a task') || '"',
      '/tasks/' || new.task_id
    );
  end if;

  return new;
end;
$$;

drop trigger if exists task_assigned_notifies on task_assignees;
create trigger task_assigned_notifies
  after insert on task_assignees
  for each row execute function notify_task_assigned();

-- A comment reaches the task owner and everyone tagged on it, except whoever
-- wrote it.
create or replace function notify_task_comment()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  v_title text;
  v_actor_name text;
begin
  select title into v_title from tasks where id = new.task_id;
  select full_name into v_actor_name from people where id = new.author_id;

  insert into notifications (person_id, kind, task_id, actor_id, summary, url)
  select
    p.id,
    'comment',
    new.task_id,
    new.author_id,
    coalesce(v_actor_name, 'Someone')
      || ' commented on "' || coalesce(v_title, 'a task') || '"',
    '/tasks/' || new.task_id
  from (
    select owner_id as id from tasks where id = new.task_id
    union
    select person_id as id from task_assignees where task_id = new.task_id
  ) p
  where p.id is distinct from new.author_id;

  return new;
end;
$$;

drop trigger if exists task_comment_notifies on task_comments;
create trigger task_comment_notifies
  after insert on task_comments
  for each row execute function notify_task_comment();

-- A direct message.
create or replace function notify_message()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  v_actor_name text;
begin
  select full_name into v_actor_name from people where id = new.sender_id;

  insert into notifications (person_id, kind, actor_id, summary, url)
  values (
    new.recipient_id,
    'message',
    new.sender_id,
    coalesce(v_actor_name, 'Someone') || ' sent you a message',
    '/messages/' || new.sender_id
  );

  return new;
end;
$$;

drop trigger if exists message_notifies on messages;
create trigger message_notifies
  after insert on messages
  for each row execute function notify_message();
